import java.util.Scanner;

public class Main {
    static long total_p, multiplier, total_cycles;
    static long[] visited_nodes = new long[1000006];

    static long mod_pow(long base, long exponent) {
        long result = 1;
        for (int bit = 30; bit >= 0; bit--) {
            result = (result * result) % 1000000007;
            if (((1L << bit) & exponent) != 0) {
                result = (result * base) % 1000000007;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_p = sc.nextLong();
        multiplier = sc.nextLong();
        total_cycles = 0;
        for (int i = 0; i < visited_nodes.length; i++) {
            visited_nodes[i] = 0;
        }
        if (multiplier == 1) {
            System.out.println(mod_pow(total_p, total_p));
            sc.close();
            return;
        }
        for (long i = 1; i < total_p; i++) {
            if (visited_nodes[(int)i] == 0) {
                visited_nodes[(int)i] = 1;
                total_cycles++;
                long current_node = (i * multiplier) % total_p;
                while (visited_nodes[(int)current_node] == 0) {
                    visited_nodes[(int)current_node] = 1;
                    current_node = (current_node * multiplier) % total_p;
                }
            }
        }
        System.out.println(mod_pow(total_p, total_cycles));
        sc.close();
    }
}
